/**
 * Generates `src/data/world.ts` — the land outline the receiver map draws.
 *
 * Run with `npm run make-world-path`. Committed output, reproducible script, same
 * arrangement as the Priyom importer: the generated file is reviewed as a diff and never
 * hand-edited.
 *
 * Source is Natural Earth's 110m land layer, which is public domain — "no permission is
 * needed to use Natural Earth", and credit is requested rather than required. It is
 * credited in the map's own attribution line anyway.
 *
 * Why a generated path rather than a map library and tiles:
 *
 * - A tile map means a runtime dependency and a third-party request on every pan, from
 *   an app whose whole claim is that nothing contacts anything the user did not ask for.
 *   OpenStreetMap's tile usage policy also discourages exactly this kind of client.
 * - It has to work with no network at all, because the Android build ships without one
 *   and the app is useful with only a saved receiver.
 * - A raster map would look absurd against a monospace phosphor terminal. An outline in
 *   the theme's own accent is both smaller and more legible here.
 *
 * The projection is equirectangular and the SVG viewBox is `0 0 360 180`, so a point is
 * simply `[lon + 180, 90 - lat]` with no scale factor anywhere. Coordinates are rounded
 * to one decimal — about 11 km, far below one screen pixel at any size this is drawn —
 * and consecutive duplicates created by that rounding are dropped.
 */

import { writeFileSync } from 'node:fs';

const SOURCE =
  'https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_110m_land.geojson';

/** One decimal degree of longitude is ~11 km; the map is never drawn near that detail. */
const PRECISION = 1;

function round(value) {
  return Number(value.toFixed(PRECISION));
}

/** A GeoJSON ring as an SVG path, or null once rounding has collapsed it to nothing. */
function ring(points) {
  const projected = [];

  for (const [lon, lat] of points) {
    const x = round(lon + 180);
    const y = round(90 - lat);
    const last = projected[projected.length - 1];
    if (last && last[0] === x && last[1] === y) continue;
    projected.push([x, y]);
  }

  // A triangle is the smallest thing that encloses any area at all.
  if (projected.length < 4) return null;

  const [start, ...rest] = projected;
  return `M${start[0]} ${start[1]}` + rest.map(([x, y]) => `L${x} ${y}`).join('') + 'Z';
}

const response = await fetch(SOURCE, { headers: { 'user-agent': 'project-echo/0.1' } });
if (!response.ok) throw new Error(`Natural Earth returned ${response.status}`);

const geojson = JSON.parse(await response.text());

const paths = [];
let dropped = 0;

for (const feature of geojson.features) {
  const { type, coordinates } = feature.geometry;
  // 110m land is Polygon and MultiPolygon only; a ring's first entry is its outline and
  // the rest are holes, which at this scale are lakes and are not drawn.
  const polygons = type === 'MultiPolygon' ? coordinates : [coordinates];

  for (const polygon of polygons) {
    const path = ring(polygon[0]);
    if (path) paths.push(path);
    else dropped += 1;
  }
}

const file = `/**
 * Land outline for the receiver map, generated by \`scripts/make-world-path.mjs\`.
 *
 * Natural Earth 110m land, public domain, projected equirectangularly into a
 * \`0 0 360 180\` viewBox so a point is \`[lon + 180, 90 - lat]\`. Do not edit by hand —
 * run \`npm run make-world-path\` and commit the diff.
 */

export const WORLD_ATTRIBUTION = 'Natural Earth';

export const WORLD_PATHS: readonly string[] = ${JSON.stringify(paths, null, 2)};
`;

writeFileSync('src/data/world.ts', file, 'utf8');

console.log(`${paths.length} land paths, ${dropped} dropped as degenerate after rounding`);
console.log(`${(file.length / 1024).toFixed(1)} kB written to src/data/world.ts`);
